const START=540,END=1080,BUFFER=60,WORK=new Set([1,2,3,4,5,6]);
const DEFAULT={"Шиномонтаж":60,"Ремонт двигуна та ходової":120,"Розвал-сходження":60,"Комп'ютерна діагностика":60,"Заправка автокондиціонера":60,"Перевірка свічок запалювання":30,"Чистка форсунок":90,"Uklon":60};
const attempts=new Map();
const base={"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin","permissions-policy":"camera=(),microphone=(),geolocation=()","x-frame-options":"DENY","content-security-policy":"default-src 'self';base-uri 'self';form-action 'self';frame-ancestors 'none';script-src 'self';style-src 'self' 'unsafe-inline';img-src 'self' data: https:;connect-src 'self';frame-src https://www.google.com https://www.google.com/maps/"};
const J=(d,s=200,extra={})=>new Response(JSON.stringify(d),{status:s,headers:new Headers({...base,...extra})});
const M=t=>{const[a,b]=String(t).split(":").map(Number);return a*60+b};
const VT=t=>/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(String(t));
const DATE=/^\d{4}-\d{2}-\d{2}$/;
const safeUrl=v=>{try{const u=new URL(String(v||""));return ["https:","http:"].includes(u.protocol)?u.href:""}catch{return ""}};
const WD=d=>WORK.has(new Date(`${d}T12:00:00`).getDay());
const OV=(a,ad,b,bd)=>a<b+bd&&a+ad>b;
function now(){const p=new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Kyiv",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date()),g=k=>p.find(x=>x.type===k)?.value||"";return{date:`${g("year")}-${g("month")}-${g("day")}`,minutes:+g("hour")*60 + +g("minute")}}
function b64(a){let s="";for(const x of a)s+=String.fromCharCode(x);return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"")}
async function sig(sec,t){const k=await crypto.subtle.importKey("raw",new TextEncoder().encode(sec),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return b64(new Uint8Array(await crypto.subtle.sign("HMAC",k,new TextEncoder().encode(t))))}
async function session(sec,r){const p=`${r}.${Date.now()}`;return`${p}.${await sig(sec,p)}`}
function cookie(req,n){const s=req.headers.get("cookie")||"",x=s.split(";").map(v=>v.trim()).find(v=>v.startsWith(n+"="));return x?decodeURIComponent(x.slice(n.length+1)):""}
function sessionSecret(e){return e.SESSION_SECRET||e.SUPERADMIN_PASSWORD||e.ADMIN_PASSWORD||""}
async function role(req,e){const sec=sessionSecret(e);if(!sec)return null;const t=cookie(req,"mehanik_session"),p=t.split(".");if(p.length!==3)return null;const[r,ts,s]=p;if(!/^(admin|superadmin)$/.test(r)||Date.now()-Number(ts)>604800000)return null;return s===await sig(sec,`${r}.${ts}`)?r:null}
async function auth(req,e,superOnly=false){const r=await role(req,e);if(!r)return{error:"Потрібна авторизація",status:401};if(superOnly&&r!=="superadmin")return{error:"Потрібні права superadmin",status:403};return{role:r}}
async function col(db,sql){try{await db.prepare(sql).run()}catch{}}
