 for(const[n,d] of Object.entries(DEFAULT)){const active=n==="Uklon"?0:1;await db.prepare(`INSERT OR IGNORE INTO service_catalog(name,duration_minutes,active,sort_order) VALUES(?,?,?,?)`).bind(n,d,active,Object.keys(DEFAULT).indexOf(n)).run()}
