async function tg(e,method,payload){if(!e.TELEGRAM_BOT_TOKEN||!e.TELEGRAM_CHAT_ID)return null;try{const r=await fetch(`https://api.telegram.org/bot${e.TELEGRAM_BOT_TOKEN}/${method}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});return await r.json()}catch{return null}}
async function audit(db,actor,action,target,details=""){try{await db.prepare(`INSERT INTO admin_logs(actor,action,target,details) VALUES(?,?,?,?)`).bind(actor,action,target,details).run()}catch{}}
function telegramText(b,id){return[`🔔 НОВА ЗАЯВКА — МЕХАНІК ПОЛТАВА`,``,`🆔 #${id}`,`👤 ${b.name}`,`📞 ${b.phone}`,`🚗 ${b.car}`,`🔧 ${b.service}`,`👥 ${b.client_type==="uklon"?"🚕 Uklon":"👤 Звичайний клієнт"}`,`📅 ${b.preferred_date}`,`🕐 ${b.preferred_time}`,b.mechanic_name?`👨‍🔧 ${b.mechanic_name}`:"👨‍🔧 Механік: не призначений",b.comment?`📝 ${b.comment}`:"📝 Коментар: немає","",b.status==="confirmed"?"🟢 ЧАС УЗГОДЖЕНО":"🟡 ЧАС ЩЕ НЕ УЗГОДЖЕНО"].join("\n")}
async function login(req,e){const ip=req.headers.get("cf-connecting-ip")||"unknown",t=Date.now(),a=attempts.get(ip)||{n:0,at:t};if(t-a.at>600000){a.n=0;a.at=t}if(a.n>=10)return J({error:"Забагато невдалих спроб. Спробуйте пізніше."},429,{"retry-after":"600"});let b;try{b=await req.json()}catch{return J({error:"Некоректний запит"},400)}const u=String(b.username||"").trim().toLowerCase(),p=String(b.password||"");let r=null;if(u==="admin"&&e.ADMIN_PASSWORD&&p===e.ADMIN_PASSWORD)r="admin";if(u==="superadmin"&&e.SUPERADMIN_PASSWORD&&p===e.SUPERADMIN_PASSWORD)r="superadmin";if(!r){a.n++;a.at=t;attempts.set(ip,a);return J({error:"Невірний логін або пароль"},401)}attempts.delete(ip);const s=await session(sessionSecret(e),r);return J({ok:true,role:r},200,{"set-cookie":`mehanik_session=${encodeURIComponent(s)}; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Strict`})}
async function services(e){const{results}=await e.DB.prepare(`SELECT id,name,description,price_from,duration_minutes FROM service_catalog WHERE active=1 ORDER BY sort_order,id`).all();return J(results||[])}
async function works(e){const{results}=await e.DB.prepare(`SELECT id,title,car,description,image_url,instagram_url,media_type,media_url FROM works WHERE published=1 ORDER BY created_at DESC LIMIT 100`).all();return J(results||[])}
async function reviews(e){const{results}=await e.DB.prepare(`SELECT id,name,rating,text,created_at FROM reviews WHERE approved=1 ORDER BY created_at DESC LIMIT 100`).all();return J(results||[])}
async function createReview(req,e){let b;try{b=await req.json()}catch{return J({error:"Некоректний запит"},400)}const r=Number(b.rating),name=String(b.name||"").trim(),text=String(b.text||"").trim();if(!name||!Number.isInteger(r)||r<1||r>5||!text||text.length>2000)return J({error:"Перевірте ім'я, оцінку та текст відгуку"},400);const x=await e.DB.prepare(`INSERT INTO reviews(name,rating,text,approved) VALUES(?,?,?,0)`).bind(name,r,text).run(),id=Number(x.meta.last_row_id),tgRow=await tg(e,"sendMessage",{chat_id:e.TELEGRAM_CHAT_ID,text:`⭐ НОВИЙ ВІДГУК #${id}\n👤 ${name}\n⭐ ${r}/5\n💬 ${text}`});if(tgRow?.result?.message_id)await e.DB.prepare(`INSERT OR REPLACE INTO review_telegram(review_id,message_id) VALUES(?,?)`).bind(id,Number(tgRow.result.message_id)).run();return J({ok:true,message:"Дякуємо! Відгук надіслано на модерацію."},201)}
async function booking(req,e){let b;try{b=await req.json()}catch{return J({error:"Некоректний запит"},400)}for(const k of ["name","phone","car","service","date"])if(!String(b[k]||"").trim())return J({error:`Не заповнено: ${k}`},400);const name=String(b.name).trim(),phone=String(b.phone).trim(),car=String(b.car).trim(),date=String(b.date),service=String(b.service).trim(),comment=String(b.note||"").trim().slice(0,2000);if(name.length>100||phone.length>40||car.length>120||comment.length>2000||!DATE.test(date)||!WD(date))return J({error:"Некоректні дані заявки"},400);if(date<now().date)return J({error:"Дата вже минула"},409);const s=await e.DB.prepare(`SELECT * FROM service_catalog WHERE name=? AND active=1`).bind(service).first();if(!s)return J({error:"Послугу не знайдено"},400);const type=b.client_type==="uklon"?"uklon":"regular",time="Узгоджується з майстром",x=await e.DB.prepare(`INSERT INTO bookings(name,phone,car,service,preferred_date,preferred_time,comment,status,client_type) VALUES(?,?,?,?,?,?,?,?,?)`).bind(name,phone,car,s.name,date,time,comment,"new",type).run(),id=Number(x.meta.last_row_id),tgRow=await tg(e,"sendMessage",{chat_id:e.TELEGRAM_CHAT_ID,text:telegramText({name,phone,car,service:s.name,preferred_date:date,preferred_time:time,comment,status:"new",client_type:type},id)});if(tgRow?.result?.message_id)await e.DB.prepare(`INSERT OR REPLACE INTO booking_telegram(booking_id,message_id) VALUES(?,?)`).bind(id,Number(tgRow.result.message_id)).run();return J({ok:true,id,message:"Заявку прийнято. Майстер зв'яжеться з вами для узгодження часу."},201)}
function elapsedNow(row){let sec=Number(row.work_elapsed_seconds||0);if(row.work_status==="running"&&row.work_started_at)sec+=Math.max(0,Math.floor((Date.now()-Date.parse(row.work_started_at))/1000));return sec}
async function autoFinishExpired(db,rows){const updates=[];for(const x of rows){const total=Math.max(1,Number(x.duration||60)*60);const elapsed=elapsedNow(x);if(x.work_status==="running"&&elapsed>=total){updates.push(db.prepare(`UPDATE bookings SET work_elapsed_seconds=?,work_started_at=NULL,work_finished_at=?,work_status='finished',status='completed' WHERE id=?`).bind(total,isoNow(),Number(x.id)));x.work_elapsed_seconds=total;x.work_started_at=null;x.work_finished_at=isoNow();x.work_status='finished';x.status='completed';}}if(updates.length)await db.batch(updates);return rows}
function isoNow(){return new Date().toISOString()}
async function adminBookings(req,e,actor){if(req.method==="GET"){const{results}=await e.DB.prepare(`SELECT b.id,b.name,b.phone,b.car,b.service,s.id service_id,b.preferred_date date,b.preferred_time time,b.comment note,b.status,b.client_type,b.created_at,b.work_started_at,b.work_finished_at,b.work_elapsed_seconds,b.work_status,bm.mechanic_id,COALESCE(m.name,'') mechanic_name,COALESCE(s.duration_minutes,60) duration FROM bookings b LEFT JOIN booking_mechanics bm ON bm.booking_id=b.id LEFT JOIN mechanics m ON m.id=bm.mechanic_id LEFT JOIN service_catalog s ON s.name=b.service ORDER BY b.created_at DESC LIMIT 500`).all();const rows=await autoFinishExpired(e.DB,results||[]);return J(rows.map(x=>{const elapsed=elapsedNow(x),total=Math.max(1,Number(x.duration||60)*60);return {...x,elapsed_seconds:Math.min(total,elapsed),remaining_seconds:Math.max(0,total-elapsed)}}))}let b;try{b=await req.json()}catch{return J({error:"Некоректний запит"},400)}const id=Number(b.id),row=await e.DB.prepare(`SELECT * FROM bookings WHERE id=?`).bind(id).first();if(!row)return J({error:"Заявку не знайдено"},404);const date=row.preferred_date;
 if(b.action==="set_client_type"){const type=b.client_type==="uklon"?"uklon":"regular";await e.DB.prepare(`UPDATE bookings SET client_type=? WHERE id=?`).bind(type,id).run();await audit(e.DB,actor,"set_client_type",`booking:${id}`,type);return J({ok:true,message:"Тип клієнта оновлено"})}
 if(b.action==="set_time"){const t=String(b.time||"");if(!VT(t))return J({error:"Час має бути у форматі HH:MM"},400);const mid=Number(b.mechanic_id);if(!mid)return J({error:"Оберіть механіка"},400);const m=await e.DB.prepare(`SELECT * FROM mechanics WHERE id=? AND active=1`).bind(mid).first();if(!m)return J({error:"Механіка не знайдена"},404);const s=await e.DB.prepare(`SELECT id,duration_minutes FROM service_catalog WHERE name=? AND active=1`).bind(row.service).first();if(!s)return J({error:"Послугу не знайдено"},404);const map=await e.DB.prepare(`SELECT 1 FROM mechanic_services WHERE mechanic_id=? AND service_id=?`).bind(mid,Number(s.id)).first();if(!map)return J({error:`${m.name} не закріплений за послугою «${row.service}»`},409);const start=M(t),dur=Number(s.duration_minutes||60),n=now();if(!DATE.test(date)||!WD(date)||date<n.date||(date===n.date&&start<n.minutes)||start<START||start+dur>END)return J({error:"Час поза графіком 09:00–18:00 або вже минув"},409);const blocked=(await e.DB.prepare(`SELECT time FROM blocked_slots WHERE date=?`).bind(date).all()).results||[];if(blocked.some(x=>VT(x.time)&&OV(start,dur,M(x.time)-BUFFER,BUFFER*2)))return J({error:"Цей час заблокований адміністратором"},409);const busy=(await e.DB.prepare(`SELECT b.preferred_time time,COALESCE(s.duration_minutes,60) dur FROM bookings b JOIN booking_mechanics bm ON bm.booking_id=b.id LEFT JOIN service_catalog s ON s.name=b.service WHERE b.preferred_date=? AND bm.mechanic_id=? AND b.id<>? AND b.status IN ('new','confirmed')`).bind(date,mid,id).all()).results||[];if(busy.some(x=>VT(x.time)&&OV(start,dur,M(x.time)-BUFFER,Number(x.dur)+BUFFER)))return J({error:"Механік зайнятий. Між роботами залишено буфер 60 хв."},409);await e.DB.batch([e.DB.prepare(`INSERT OR REPLACE INTO booking_mechanics(booking_id,mechanic_id) VALUES(?,?)`).bind(id,mid),e.DB.prepare(`UPDATE bookings SET preferred_time=?,status='confirmed' WHERE id=?`).bind(t,id)]);const tgRow=await e.DB.prepare(`SELECT message_id FROM booking_telegram WHERE booking_id=?`).bind(id).first();if(tgRow?.message_id)await tg(e,"editMessageText",{chat_id:e.TELEGRAM_CHAT_ID,message_id:Number(tgRow.message_id),text:telegramText({name:row.name,phone:row.phone,car:row.car,service:row.service,preferred_date:date,preferred_time:t,comment:row.comment,mechanic_name:m.name,status:"confirmed",client_type:row.client_type},id)});await audit(e.DB,actor,"set_time",`booking:${id}`,`${t};mechanic:${mid}`);return J({ok:true,message:`Час ${t} узгоджено з ${m.name}.`})}
 if(b.action==="start_work"){const bm=await e.DB.prepare(`SELECT mechanic_id FROM booking_mechanics WHERE booking_id=?`).bind(id).first();if(!bm)return J({error:"Спочатку призначте механіка і час"},409);if(row.work_status==="running")return J({error:"Робота вже запущена"},409);const start=isoNow();await e.DB.prepare(`UPDATE bookings SET work_started_at=?,work_finished_at=NULL,work_status='running' WHERE id=?`).bind(start,id).run();await audit(e.DB,actor,"start_work",`booking:${id}`,`mechanic:${bm.mechanic_id}`);return J({ok:true,message:"Таймер роботи запущено"})}
 if(b.action==="pause_work"){if(row.work_status!=="running"||!row.work_started_at)return J({error:"Робота не запущена"},409);const add=Math.max(0,Math.floor((Date.now()-Date.parse(row.work_started_at))/1000));await e.DB.prepare(`UPDATE bookings SET work_elapsed_seconds=work_elapsed_seconds+?,work_started_at=NULL,work_status='paused' WHERE id=?`).bind(add,id).run();await audit(e.DB,actor,"pause_work",`booking:${id}`);return J({ok:true,message:"Таймер призупинено"})}
 if(b.action==="finish_work"){if(!['running','paused'].includes(row.work_status))return J({error:"Спочатку запустіть роботу"},409);let sec=Number(row.work_elapsed_seconds||0);if(row.work_status==="running"&&row.work_started_at)sec+=Math.max(0,Math.floor((Date.now()-Date.parse(row.work_started_at))/1000));const total=Math.max(1,Number((await e.DB.prepare(`SELECT duration_minutes FROM service_catalog WHERE name=?`).bind(row.service).first())?.duration_minutes||60)*60);sec=Math.min(total,sec);await e.DB.prepare(`UPDATE bookings SET work_elapsed_seconds=?,work_started_at=NULL,work_finished_at=?,work_status='finished',status='completed' WHERE id=?`).bind(sec,isoNow(),id).run();await audit(e.DB,actor,"finish_work",`booking:${id}`,`${sec}s`);return J({ok:true,message:"Роботу завершено"})}
 if(b.action==="reset_work"){await e.DB.prepare(`UPDATE bookings SET work_started_at=NULL,work_finished_at=NULL,work_elapsed_seconds=0,work_status='not_started' WHERE id=?`).bind(id).run();await audit(e.DB,actor,"reset_work",`booking:${id}`);return J({ok:true,message:"Таймер скинуто"})}
 const st={confirm:"confirmed",complete:"completed",cancel:"cancelled",reopen:"new"}[b.action];if(st){await e.DB.prepare(`UPDATE bookings SET status=? WHERE id=?`).bind(st,id).run();await audit(e.DB,actor,b.action,`booking:${id}`);return J({ok:true,message:"Статус заявки оновлено"})}
 if(b.action==="archive"){const tgRow=await e.DB.prepare(`SELECT message_id FROM booking_telegram WHERE booking_id=?`).bind(id).first();if(tgRow?.message_id)await tg(e,"deleteMessage",{chat_id:e.TELEGRAM_CHAT_ID,message_id:Number(tgRow.message_id)});await e.DB.prepare(`INSERT OR REPLACE INTO booking_history(id,name,phone,car,service,preferred_date,preferred_time,comment,status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)`).bind(id,row.name,row.phone,row.car,row.service,row.preferred_date,row.preferred_time,row.comment||"",row.status,row.created_at).run();await e.DB.batch([e.DB.prepare(`DELETE FROM booking_mechanics WHERE booking_id=?`).bind(id),e.DB.prepare(`DELETE FROM booking_telegram WHERE booking_id=?`).bind(id),e.DB.prepare(`DELETE FROM bookings WHERE id=?`).bind(id)]);await audit(e.DB,actor,"archive",`booking:${id}`);return J({ok:true,message:"Заявку перенесено в архів"})}
 return J({error:"Невідома дія"},400)}
