const AI_MODEL="@cf/meta/llama-3.1-8b-instruct-fast";
function aiAnswerText(x){return String(x?.response??x?.text??x?.output_text??"").trim()}
async function adminAI(req,e,actor){
  if(!e.AI||typeof e.AI.run!=="function")return J({error:"Workers AI не підключений до Worker"},503);
  let b;try{b=await req.json()}catch{return J({error:"Некоректний запит"},400)}
  const task=String(b.task||"").trim();
  if(!task)return J({error:"Вкажіть завдання для AI"},400);
  if(task.length>6000)return J({error:"Запит занадто великий"},413);
  let context="";
  const bookingId=Number(b.booking_id||0);
  if(Number.isInteger(bookingId)&&bookingId>0){
    const row=await e.DB.prepare(`SELECT b.id,b.car,b.service,b.preferred_date,b.preferred_time,b.comment,b.status,b.client_type,COALESCE(m.name,'') mechanic_name,COALESCE(s.duration_minutes,60) duration FROM bookings b LEFT JOIN booking_mechanics bm ON bm.booking_id=b.id LEFT JOIN mechanics m ON m.id=bm.mechanic_id LEFT JOIN service_catalog s ON s.name=b.service WHERE b.id=?`).bind(bookingId).first();
    if(!row)return J({error:"Заявку не знайдено"},404);
    context=`\nКонтекст заявки #${row.id}:\nАвтомобіль: ${row.car}\nПослуга: ${row.service}\nНорма часу: ${row.duration} хв\nДата: ${row.preferred_date}\nУзгоджений час: ${row.preferred_time}\nСтатус: ${row.status}\nТип клієнта: ${row.client_type==='uklon'?'Uklon':'звичайний'}\nМеханік: ${row.mechanic_name||'не призначений'}\nОпис/коментар клієнта: ${row.comment||'немає'}\n`;
  }
  const system=`Ти внутрішній AI-помічник СТО «Механік Полтава». Відповідай українською, коротко і практично. Ти НЕ механік і НЕ ставиш остаточний діагноз. Не вигадуй несправності, ціни, норми часу, факти або результати огляду. Остаточне рішення щодо автомобіля, ремонту, запчастин і безпеки приймає механік після огляду та діагностики. Якщо даних недостатньо, прямо вкажи, чого бракує. Для текстів клієнту пиши ввічливо і без технічної самовпевненості. Для SEO/маркетингу не вигадуй цифри чи переваги, яких немає в контексті.`;
  try{
    const out=await e.AI.run(AI_MODEL,{messages:[{role:"system",content:system},{role:"user",content:`Завдання адміністратора:\n${task}${context}`}],max_tokens:700,temperature:0.2});
    const answer=aiAnswerText(out);if(!answer)throw new Error("AI не повернув відповідь");
    await audit(e.DB,actor,"ai_assist",bookingId?`booking:${bookingId}`:"ai",task.slice(0,500));
    return J({ok:true,answer,model:AI_MODEL});
  }catch(err){console.error("Workers AI error",err);return J({error:"AI тимчасово недоступний"},503)}
}


const PUBLIC_AI_MODEL="@cf/meta/llama-3.1-8b-instruct-fast";
async function publicAI(req,e){
 if(!e.AI||typeof e.AI.run!=="function")return J({error:"AI тимчасово недоступний"},503);
 let b;try{b=await req.json()}catch{return J({error:"Некоректний запит"},400)}
 const message=String(b.message||"").trim();if(!message||message.length>1200)return J({error:"Некоректне питання"},400);
 const services=(await e.DB.prepare(`SELECT name,description,price_from,duration_minutes FROM service_catalog WHERE active=1 AND name<>'Uklon' ORDER BY sort_order,id`).all()).results||[];
 const rates=(await e.DB.prepare(`SELECT rate,fetched_at,source FROM currency_rates WHERE currency='USD' ORDER BY id DESC LIMIT 1`).all()).results||[];
 const catalog=services.map(s=>`${s.name}: ${s.price_from==null?"ціна уточнюється":`від ${s.price_from} грн`}; норма ${s.duration_minutes} хв`).join("\n");
 const usd=rates[0]?`USD: ${rates[0].rate} грн, оновлено ${rates[0].fetched_at}`:"Курс USD ще не завантажено";
 const system=`Ти публічний AI-помічник офіційного сайту СТО «Механік Полтава». Відповідай українською, стисло і практично. Адреса: Решетилівська 53, Полтава. Графік Пн–Сб 09:00–18:00. Клієнт обирає послугу і день, точний час узгоджує майстер. Не вигадуй ціни, наявність, час, результати діагностики чи гарантії. Не став остаточний діагноз. Uklon є внутрішньою ознакою заявки і клієнту його не пропонуй. Якщо потрібен ремонт, запропонуй запис на сайті. Актуальні послуги:\n${catalog}\n${usd}`;
 try{const out=await e.AI.run(PUBLIC_AI_MODEL,{messages:[{role:"system",content:system},{role:"user",content:message}],max_tokens:500,temperature:.2});const answer=aiAnswerText(out);return answer?J({ok:true,answer}):J({error:"AI не повернув відповідь"},503)}catch(err){console.error(err);return J({error:"AI тимчасово недоступний"},503)}
}
async function fetchUsd(e){
 const url="https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?valcode=USD&json";
 const r=await fetch(url,{headers:{"user-agent":"Mehanik-Poltava/1.0"}});if(!r.ok)throw Error("NBU HTTP "+r.status);
 const d=await r.json();const rate=Number(d?.[0]?.rate);if(!Number.isFinite(rate))throw Error("NBU invalid rate");
 await e.DB.prepare(`INSERT INTO currency_rates(currency,rate,source,fetched_at) VALUES('USD',?,?,?)`).bind(rate,"NBU",isoNow()).run();
 return rate;
}
function stripHtml(s){return String(s||"").replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<style[\s\S]*?<\/style>/gi," ").replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim().slice(0,18000)}
async function updateMarket(e){
 const srcs=(await e.DB.prepare(`SELECT * FROM market_sources WHERE active=1`).all()).results||[];
 let done=0;
 for(const s of srcs){
  try{
   const r=await fetch(s.url,{headers:{"user-agent":"Mozilla/5.0 Mehanik-Poltava market monitor"}});const text=stripHtml(await r.text());
   let summary="";
   if(e.AI&&text){const out=await e.AI.run(PUBLIC_AI_MODEL,{messages:[
    {role:"system",content:"Ти аналітик цін СТО. Проаналізуй лише наданий текст. Не вигадуй цифри. Витягни згадки про ціни автомобільних робіт, норми часу та валютні фактори. Якщо точних цін на конкретні роботи немає, прямо напиши це."},
    {role:"user",content:`Джерело: ${s.name}\nURL: ${s.url}\nТекст:\n${text}`}],max_tokens:900,temperature:.1});summary=aiAnswerText(out)}
   await e.DB.prepare(`INSERT INTO market_snapshots(source_id,content,fetched_at,ai_summary,status) VALUES(?,?,?,?,?)`).bind(s.id,text.slice(0,6000),isoNow(),summary,"ok").run();done++;
  }catch(err){await e.DB.prepare(`INSERT INTO market_snapshots(source_id,content,fetched_at,ai_summary,status) VALUES(?,?,?,?,?)`).bind(s.id,"",isoNow(),String(err.message||err),"error").run()}
 }
 return done;
}
async function analytics(req,e){
 const from=String(new URL(req.url).searchParams.get("from")||"").trim(),to=String(new URL(req.url).searchParams.get("to")||"").trim();
 const where=DATE.test(from)&&DATE.test(to)?"WHERE b.preferred_date BETWEEN ? AND ?":"";
 const binds=where?[from,to]:[];
 const rows=(await e.DB.prepare(`SELECT m.id,m.name,m.role,COUNT(b.id) jobs,COALESCE(SUM(s.duration_minutes),0) norm_minutes,COALESCE(SUM(b.work_elapsed_seconds),0) elapsed_seconds,COALESCE(SUM(CASE WHEN b.status='completed' THEN s.price_from ELSE 0 END),0) revenue,COALESCE(SUM(CASE WHEN b.status='completed' THEN 1 ELSE 0 END),0) completed,COALESCE(SUM(CASE WHEN b.status='cancelled' THEN 1 ELSE 0 END),0) cancelled FROM mechanics m LEFT JOIN booking_mechanics bm ON bm.mechanic_id=m.id LEFT JOIN bookings b ON b.id=bm.booking_id ${where?where:""} LEFT JOIN service_catalog s ON s.name=b.service GROUP BY m.id ORDER BY completed DESC`).bind(...binds).all()).results||[];
 const total=(await e.DB.prepare(`SELECT COUNT(*) jobs,COALESCE(SUM(work_elapsed_seconds),0) elapsed_seconds,COALESCE(SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END),0) completed FROM bookings b ${where}`).bind(...binds).first())||{};
 return J({period:{from:from||null,to:to||null},mechanics:rows.map(x=>({...x,elapsed_hours:+(Number(x.elapsed_seconds)/3600).toFixed(2),norm_hours:+(Number(x.norm_minutes)/60).toFixed(2),utilization:+(Number(x.norm_minutes)?(Number(x.elapsed_seconds)/60/Number(x.norm_minutes)*100):0).toFixed(1)})),total});
}

async function generatePriceRecommendations(e){
 if(!e.AI)return [];
 const services=(await e.DB.prepare(`SELECT id,name,price_from,duration_minutes FROM service_catalog WHERE active=1 AND name<>'Uklon'`).all()).results||[];
 const snaps=(await e.DB.prepare(`SELECT m.name source_name,ms.ai_summary FROM market_snapshots ms JOIN market_sources m ON m.id=ms.source_id WHERE ms.status='ok' ORDER BY ms.id DESC LIMIT 12`).all()).results||[];
 const usd=await e.DB.prepare(`SELECT rate,fetched_at FROM currency_rates WHERE currency='USD' ORDER BY id DESC LIMIT 1`).first();
 const prompt=`Порівняй поточний прайс СТО з наведеними ринковими джерелами. Не вигадуй ціни. Поверни ТІЛЬКИ JSON-масив об'єктів виду {"service_id":1,"new_price":900,"market_min":700,"market_median":850,"market_max":1200,"reason":"коротко"}.
Якщо для послуги немає достатніх точних ринкових даних, НЕ додавай її. new_price округлюй до 50 грн.
Поточні послуги:
${JSON.stringify(services)}
Ринкові звіти:
${JSON.stringify(snaps)}
USD: ${usd?usd.rate:"немає"}`;
 try{
  const out=await e.AI.run(PUBLIC_AI_MODEL,{messages:[
   {role:"system",content:"Ти аналітик цін СТО. Не вигадуй дані. Поверни лише валідний JSON-масив без markdown."},
   {role:"user",content:prompt}],max_tokens:1200,temperature:.1});
  let text=aiAnswerText(out).replace(/^```json\s*/,"").replace(/^```\s*/,"").replace(/```$/,"").trim();
  const arr=JSON.parse(text);if(!Array.isArray(arr))return [];
  const valid=new Map(services.map(s=>[Number(s.id),s]));
  const outRows=[];
  for(const x of arr){
   const s=valid.get(Number(x.service_id));const np=Number(x.new_price);
   if(!s||!Number.isFinite(np)||np<0)continue;
   const r=await e.DB.prepare(`INSERT INTO price_recommendations(service_id,old_price,new_price,market_min,market_median,market_max,reason,applied) VALUES(?,?,?,?,?,?,?,0)`).bind(s.id,s.price_from,np,Number(x.market_min)||null,Number(x.market_median)||null,Number(x.market_max)||null,String(x.reason||"").slice(0,500)).run();
   outRows.push({id:Number(r.meta.last_row_id),service_id:s.id,service_name:s.name,old_price:s.price_from,new_price:np,market_min:x.market_min,market_median:x.market_median,market_max:x.market_max,reason:String(x.reason||"")});
  }
  return outRows;
 }catch(err){console.error("price recommendations:",err);return []}
}
async function marketAdmin(req,e){
 if(req.method==="GET"){const sources=(await e.DB.prepare(`SELECT * FROM market_sources ORDER BY id`).all()).results||[];const snaps=(await e.DB.prepare(`SELECT ms.*,m.name source_name,m.url FROM market_snapshots ms JOIN market_sources m ON m.id=ms.source_id ORDER BY ms.id DESC LIMIT 50`).all()).results||[];const rate=await e.DB.prepare(`SELECT * FROM currency_rates WHERE currency='USD' ORDER BY id DESC LIMIT 1`).first();const recommendations=(await e.DB.prepare(`SELECT pr.*,s.name service_name FROM price_recommendations pr JOIN service_catalog s ON s.id=pr.service_id WHERE pr.applied=0 ORDER BY pr.id DESC LIMIT 30`).all()).results||[];return J({sources,snapshots:snaps,usd:rate||null,recommendations})}
 let b;try{b=await req.json()}catch{return J({error:"Некоректний запит"},400)}
 if(b.action==="sync"){const rate=await fetchUsd(e);const n=await updateMarket(e);const recommendations=await generatePriceRecommendations(e);await audit(e.DB,"superadmin","market_sync","market",`sources:${n};usd:${rate};recommendations:${recommendations.length}`);return J({ok:true,rate,updated_sources:n,recommendations})}
 if(b.action==="add_source"){if(!b.name||!safeUrl(b.url))return J({error:"Некоректне джерело"},400);await e.DB.prepare(`INSERT INTO market_sources(name,url,active) VALUES(?,?,1)`).bind(String(b.name).slice(0,120),safeUrl(b.url)).run();return J({ok:true,message:"Джерело додано"})}
 if(b.action==="apply_price"){const id=Number(b.id);const rec=await e.DB.prepare(`SELECT * FROM price_recommendations WHERE id=? AND applied=0`).bind(id).first();if(!rec)return J({error:"Рекомендацію не знайдено"},404);await e.DB.prepare(`UPDATE service_catalog SET price_from=? WHERE id=?`).bind(rec.new_price,rec.service_id).run();await e.DB.prepare(`UPDATE price_recommendations SET applied=1 WHERE id=?`).bind(id).run();await audit(e.DB,"superadmin","apply_price",`service:${rec.service_id}`,`${rec.old_price}->${rec.new_price}`);return J({ok:true,message:"Нову ціну застосовано"})}
 return J({error:"Невідома дія"},400);
}


// ---------------- Google Drive OAuth + media storage ----------------
const GOOGLE_AUTH_URL="https://accounts.google.com/o/oauth2/v2/auth";
const GOOGLE_TOKEN_URL="https://oauth2.googleapis.com/token";
const GOOGLE_DRIVE_API="https://www.googleapis.com/drive/v3";
const GOOGLE_UPLOAD_API="https://www.googleapis.com/upload/drive/v3/files";
const GOOGLE_SCOPE="https://www.googleapis.com/auth/drive.file";

async function sha256Bytes(text){return new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(text)))}
async function aesKey(secret){return crypto.subtle.importKey("raw",await sha256Bytes(secret),"AES-GCM",false,["encrypt","decrypt"])}
function bytesToB64(bytes){let s="";for(const b of bytes)s+=String.fromCharCode(b);return btoa(s)}
function b64ToBytes(text){
  const normalized=String(text||"").replace(/-/g,"+").replace(/_/g,"/");
  const padded=normalized+"=".repeat((4-normalized.length%4)%4);
  return Uint8Array.from(atob(padded),c=>c.charCodeAt(0));
}
async function encryptSecret(secret,value){const iv=crypto.getRandomValues(new Uint8Array(12));const key=await aesKey(secret);const data=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,new TextEncoder().encode(value));return `${b64(iv)}.${b64(new Uint8Array(data))}`}
async function decryptSecret(secret,value){const [iv,data]=String(value||"").split(".");if(!iv||!data)throw Error("Зашифрований токен відсутній");const key=await aesKey(secret);const plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:b64ToBytes(iv)},key,b64ToBytes(data));return new TextDecoder().decode(plain)}
async function googleState(e,r){const sec=sessionSecret(e);const payload=`${r}.${Date.now()}.${crypto.randomUUID()}`;return `${b64(new TextEncoder().encode(payload))}.${await sig(sec,payload)}`}
async function verifyGoogleState(e,state){const [a,s]=String(state||"").split(".");if(!a||!s)return null;let payload;try{payload=new TextDecoder().decode(b64ToBytes(a))}catch{return null}const [r,ts]=payload.split(".");if(!/^(admin|superadmin)$/.test(r)||!Number.isFinite(Number(ts))||Date.now()-Number(ts)>600000)return null;return s===await sig(sessionSecret(e),payload)?r:null}
async function googleStart(req,e){const a=await auth(req,e);if(a.error)return J({error:a.error},a.status);if(!e.GOOGLE_CLIENT_ID||!e.GOOGLE_CLIENT_SECRET||!e.GOOGLE_DRIVE_FOLDER_ID)return J({error:"Google Drive не налаштований у Cloudflare Secrets/Variables"},503);const state=await googleState(e,a.role);const u=new URL(GOOGLE_AUTH_URL);u.searchParams.set("client_id",e.GOOGLE_CLIENT_ID);u.searchParams.set("redirect_uri",`${new URL(req.url).origin}/api/google/callback`);u.searchParams.set("response_type","code");u.searchParams.set("access_type","offline");u.searchParams.set("prompt","consent");u.searchParams.set("scope",GOOGLE_SCOPE);u.searchParams.set("state",state);return Response.redirect(u.toString(),302)}
async function googleCallback(req,e){if(!e.GOOGLE_CLIENT_ID||!e.GOOGLE_CLIENT_SECRET)return new Response("Google OAuth не налаштований",{status:503});const u=new URL(req.url),state=await verifyGoogleState(e,u.searchParams.get("state"));if(!state)return new Response("Недійсний або прострочений OAuth state",{status:400});const code=u.searchParams.get("code");if(!code)return new Response("Google не повернув authorization code",{status:400});const body=new URLSearchParams({code,client_id:e.GOOGLE_CLIENT_ID,client_secret:e.GOOGLE_CLIENT_SECRET,redirect_uri:`${u.origin}/api/google/callback`,grant_type:"authorization_code"});const r=await fetch(GOOGLE_TOKEN_URL,{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded"},body});const d=await r.json().catch(()=>({}));if(!r.ok||!d.refresh_token)return new Response(`<h1>Google OAuth помилка</h1><pre>${escHtml(d.error_description||d.error||"Не отримано refresh token")}</pre>`,{status:502,headers:{"content-type":"text/html; charset=utf-8"}});const enc=await encryptSecret(sessionSecret(e),d.refresh_token);await e.DB.prepare(`INSERT INTO google_oauth(id,refresh_token_enc,updated_at) VALUES(1,?,datetime('now')) ON CONFLICT(id) DO UPDATE SET refresh_token_enc=excluded.refresh_token_enc,updated_at=datetime('now')`).bind(enc).run();return new Response(`<!doctype html><meta charset="utf-8"><title>Google Drive підключено</title><style>body{font-family:system-ui;background:#0b0d10;color:#fff;padding:30px;max-width:700px;margin:auto}a{display:inline-block;background:#ffbd00;color:#111;padding:12px 18px;border-radius:10px;text-decoration:none;font-weight:800}</style><h1>✅ Google Drive підключено</h1><p>Авторизація завершена. Токен збережено зашифрованим у Cloudflare D1. Його не потрібно копіювати вручну.</p><a href="/admin.html">Повернутися в адмінку</a>`,{status:200,headers:{"content-type":"text/html; charset=utf-8"}})}
async function googleAccessToken(e){const row=await e.DB.prepare(`SELECT refresh_token_enc FROM google_oauth WHERE id=1`).first();if(!row?.refresh_token_enc)throw Error("Google Drive не підключений. Відкрийте підключення Google Drive в адмінці.");const refresh=await decryptSecret(sessionSecret(e),row.refresh_token_enc);const body=new URLSearchParams({client_id:e.GOOGLE_CLIENT_ID,client_secret:e.GOOGLE_CLIENT_SECRET,refresh_token:refresh,grant_type:"refresh_token"});const r=await fetch(GOOGLE_TOKEN_URL,{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded"},body});const d=await r.json().catch(()=>({}));if(!r.ok||!d.access_token)throw Error("Не вдалося оновити Google access token");return d.access_token}
async function googleStatus(req,e){
 const a=await auth(req,e);if(a.error)return J({error:a.error},a.status);
 const row=await e.DB.prepare(`SELECT id,updated_at FROM google_oauth WHERE id=1`).first();
 if(!row)return J({connected:false,configured:!!(e.GOOGLE_CLIENT_ID&&e.GOOGLE_CLIENT_SECRET&&e.GOOGLE_DRIVE_FOLDER_ID),folder_id:e.GOOGLE_DRIVE_FOLDER_ID||null});
 try{
  const token=await googleAccessToken(e);
  const r=await fetch(`${GOOGLE_DRIVE_API}/files/${encodeURIComponent(e.GOOGLE_DRIVE_FOLDER_ID)}?fields=id,name,mimeType,trashed&supportsAllDrives=true`,{headers:{Authorization:`Bearer ${token}`}});
  const d=await r.json().catch(()=>({}));
  if(!r.ok) return J({connected:true,configured:true,folder_id:e.GOOGLE_DRIVE_FOLDER_ID||null,folder_ok:false,folder_error:d.error?.message||`Google Drive HTTP ${r.status}`,updated_at:row.updated_at||null});
  return J({connected:true,configured:true,folder_id:d.id,folder_name:d.name,folder_ok:d.mimeType==='application/vnd.google-apps.folder'&&!d.trashed,updated_at:row.updated_at||null});
 }catch(err){
  return J({connected:true,configured:true,folder_id:e.GOOGLE_DRIVE_FOLDER_ID||null,folder_ok:false,folder_error:String(err.message||err),updated_at:row.updated_at||null});
 }
}
async function driveUpload(req,e){const a=await auth(req,e,true);if(a.error)return J({error:a.error},a.status);const ct=req.headers.get("content-type")||"";if(!ct.includes("multipart/form-data"))return J({error:"Потрібен multipart/form-data"},400);const form=await req.formData();const file=form.get("file");if(!(file instanceof File)||!file.size)return J({error:"Файл не вибрано"},400);if(file.size>90*1024*1024)return J({error:"Файл завеликий для цього режиму. Максимум 90 МБ."},413);const kind=String(form.get("media_type")||"")==="video"?"video":"image";const allowed=kind==="video"?["video/mp4","video/webm","video/quicktime"]:["image/jpeg","image/png","image/webp","image/gif"];if(file.type&&!allowed.includes(file.type))return J({error:"Непідтримуваний формат файлу"},400);const token=await googleAccessToken(e);
const folderCheck=await fetch(`${GOOGLE_DRIVE_API}/files/${encodeURIComponent(e.GOOGLE_DRIVE_FOLDER_ID)}?fields=id,name,mimeType,trashed&supportsAllDrives=true`,{headers:{Authorization:`Bearer ${token}`}});
const folderData=await folderCheck.json().catch(()=>({}));
if(!folderCheck.ok||folderData.mimeType!=="application/vnd.google-apps.folder"||folderData.trashed)throw Error(folderData.error?.message||"Папку Google Drive не знайдено або немає доступу");
const metadata={name:String(form.get("filename")||file.name).slice(0,180),mimeType:file.type||"application/octet-stream",parents:[e.GOOGLE_DRIVE_FOLDER_ID]};const init=await fetch(`${GOOGLE_UPLOAD_API}?uploadType=resumable&fields=id,name,mimeType,size,webViewLink`,{method:"POST",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json; charset=UTF-8","X-Upload-Content-Type":file.type||"application/octet-stream","X-Upload-Content-Length":String(file.size)},body:JSON.stringify(metadata)});if(!init.ok){const d=await init.json().catch(()=>({}));throw Error(d.error?.message||`Google Drive upload init HTTP ${init.status}`)}const location=init.headers.get("location");if(!location)throw Error("Google Drive не повернув upload session");const put=await fetch(location,{method:"PUT",headers:{"Content-Length":String(file.size)},body:file});const d=await put.json().catch(()=>({}));if(!put.ok||!d.id)throw Error(d.error?.message||`Google Drive upload HTTP ${put.status}`);await e.DB.prepare(`INSERT OR REPLACE INTO drive_media(id,name,mime_type,size_bytes) VALUES(?,?,?,?)`).bind(String(d.id),String(d.name||file.name),String(d.mimeType||file.type||"application/octet-stream"),Number(d.size||file.size)).run();await audit(e.DB,a.role,"drive_upload",String(d.id),String(d.name||file.name));return J({ok:true,id:String(d.id),name:d.name,mimeType:d.mimeType,size:Number(d.size||file.size),url:new URL(`/api/media/${encodeURIComponent(d.id)}`,req.url).href,type:kind})}
async function driveDeleteById(e,id){const token=await googleAccessToken(e);const r=await fetch(`${GOOGLE_DRIVE_API}/files/${encodeURIComponent(id)}`,{method:"DELETE",headers:{Authorization:`Bearer ${token}`}});if(!r.ok&&r.status!==404){const d=await r.json().catch(()=>({}));throw Error(d.error?.message||`Google Drive HTTP ${r.status}`)}await e.DB.prepare(`DELETE FROM drive_media WHERE id=?`).bind(id).run();return true}
async function driveDelete(req,e){const a=await auth(req,e,true);if(a.error)return J({error:a.error},a.status);const id=String(new URL(req.url).searchParams.get("id")||"");if(!id)return J({error:"Не вказано ID файлу"},400);const token=await googleAccessToken(e);const r=await fetch(`${GOOGLE_DRIVE_API}/files/${encodeURIComponent(id)}`,{method:"DELETE",headers:{Authorization:`Bearer ${token}`}});if(!r.ok&&r.status!==404){const d=await r.json().catch(()=>({}));return J({error:d.error?.message||`Google Drive HTTP ${r.status}`},502)}await e.DB.prepare(`DELETE FROM drive_media WHERE id=?`).bind(id).run();return J({ok:true,message:"Файл видалено з Google Drive"})}
async function mediaProxy(req,e,id){const row=await e.DB.prepare(`SELECT mime_type,name FROM drive_media WHERE id=?`).bind(id).first();if(!row)return new Response("Media not found",{status:404,headers:base});const token=await googleAccessToken(e);const headers={Authorization:`Bearer ${token}`};const range=req.headers.get("range");if(range)headers.Range=range;const r=await fetch(`${GOOGLE_DRIVE_API}/files/${encodeURIComponent(id)}?alt=media`,{headers});if(!r.ok)return new Response("Media unavailable",{status:r.status,headers:base});const h=new Headers();h.set("content-type",r.headers.get("content-type")||row?.mime_type||"application/octet-stream");h.set("cache-control","public, max-age=3600");h.set("accept-ranges","bytes");if(r.headers.get("content-range"))h.set("content-range",r.headers.get("content-range"));if(r.headers.get("content-length"))h.set("content-length",r.headers.get("content-length"));h.set("content-disposition",`inline; filename*=UTF-8''${encodeURIComponent(row?.name||id)}`);return new Response(r.body,{status:r.status,headers:h})}

async function api(req,e,u){if(req.method==="OPTIONS")return new Response(null,{status:204,headers:base});await ensure(e.DB);if(u.pathname==="/api/google/start"&&req.method==="GET")return googleStart(req,e);if(u.pathname==="/api/google/callback"&&req.method==="GET")return googleCallback(req,e);if(u.pathname==="/api/media/status"&&req.method==="GET")return googleStatus(req,e);if(u.pathname==="/api/media/upload"&&req.method==="POST")return driveUpload(req,e);if(u.pathname==="/api/media/delete"&&req.method==="DELETE")return driveDelete(req,e);if(u.pathname.startsWith("/api/media/")&&req.method==="GET")return mediaProxy(req,e,u.pathname.slice("/api/media/".length));if(u.pathname==="/api/auth/login"&&req.method==="POST")return login(req,e);if(u.pathname==="/api/auth/logout"&&req.method==="POST")return J({ok:true},200,{"set-cookie":"mehanik_session=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict"});if(u.pathname==="/api/ai"&&req.method==="POST")return publicAI(req,e);if(u.pathname==="/api/services"&&req.method==="GET")return services(e);if(u.pathname==="/api/works"&&req.method==="GET")return works(e);if(u.pathname==="/api/reviews"&&req.method==="GET")return reviews(e);if(u.pathname==="/api/reviews"&&req.method==="POST")return createReview(req,e);if(u.pathname==="/api/bookings"&&req.method==="POST")return booking(req,e);if(u.pathname==="/api/admin/analytics"&&req.method==="GET"){const a=await auth(req,e);if(a.error)return J({error:a.error},a.status);return analytics(req,e)}if(u.pathname.startsWith("/api/admin/")){const a=await auth(req,e);if(a.error)return J({error:a.error},a.status);const r=a.role;if(u.pathname==="/api/admin/ai"&&req.method==="POST")return adminAI(req,e,r);if(u.pathname==="/api/admin/market"&&req.method==="GET")return marketAdmin(req,e);if(u.pathname==="/api/admin/market"&&req.method==="POST"){if(r!=="superadmin")return J({error:"Потрібні права superadmin"},403);return marketAdmin(req,e)}if(u.pathname==="/api/admin/bookings")return adminBookings(req,e,r);if(u.pathname==="/api/admin/services")return adminServices(req,e,r);if(u.pathname==="/api/admin/mechanics")return adminMechanics(req,e);if(u.pathname==="/api/admin/reviews")return adminReviews(req,e);if(u.pathname==="/api/admin/works")return adminWorks(req,e);if(u.pathname==="/api/admin/history")return history(req,e);if(u.pathname==="/api/admin/blocks")return blocks(req,e);if(u.pathname==="/api/admin/logs"){const s=await auth(req,e,true);if(s.error)return J({error:s.error},s.status);return logs(req,e)}return J({error:"API route not found"},404)}return null}
function secureAsset(resp){const h=new Headers(resp.headers);for(const[k,v] of Object.entries(base))if(!h.has(k)||k.startsWith("content-security-policy"))h.set(k,v);return new Response(resp.body,{status:resp.status,statusText:resp.statusText,headers:h})}
async function scheduled(e){
 try{await fetchUsd(e)}catch(err){console.error("USD sync:",err)}
 try{await updateMarket(e)}catch(err){console.error("Market sync:",err)}
}
export default{async scheduled(event,e){await scheduled(e)},async fetch(req,e){const u=new URL(req.url);try{const r=await api(req,e,u);if(r)return r;if(e.ASSETS)return secureAsset(await e.ASSETS.fetch(req));return new Response("Not Found",{status:404,headers:base})}catch(x){console.error(x);return J({error:"Внутрішня помилка сервера"},500)}}};
